17	package org.springframework.boot.context.properties.bind;
18	
19	import java.util.Collection;
20	import java.util.EnumMap;
21	import java.util.Map;
22	import java.util.Properties;
23	import java.util.function.Supplier;
24	
25	import org.jspecify.annotations.Nullable;
26	
27	import org.springframework.boot.context.properties.bind.Binder.Context;
28	import org.springframework.boot.context.properties.source.ConfigurationProperty;
29	import org.springframework.boot.context.properties.source.ConfigurationPropertyName;
30	import org.springframework.boot.context.properties.source.ConfigurationPropertyName.Form;
31	import org.springframework.boot.context.properties.source.ConfigurationPropertySource;
32	import org.springframework.boot.context.properties.source.ConfigurationPropertyState;
33	import org.springframework.boot.context.properties.source.IterableConfigurationPropertySource;
34	import org.springframework.core.CollectionFactory;
35	import org.springframework.core.ResolvableType;
36	
37	/**
38	 * {@link AggregateBinder} for Maps.
39	 *
40	 * @author Phillip Webb
41	 * @author Madhura Bhave
42	 * @author Ahmed El Amraouiyine
43	 */
44	class MapBinder extends AggregateBinder<Map<Object, Object>> {
45	
46		private static final Bindable<Map<String, String>> STRING_STRING_MAP = Bindable.mapOf(String.class, String.class);
47	
48		MapBinder(Context context) {
49			super(context);
50		}
51	
52		@Override
53		protected boolean isAllowRecursiveBinding(@Nullable ConfigurationPropertySource source) {
54			return true;
55		}
56	
57		@Override
58		protected @Nullable Object bindAggregate(ConfigurationPropertyName name, Bindable<?> target,
59				AggregateElementBinder elementBinder) {
60			Bindable<?> resolvedTarget = resolveTarget(target);
61			boolean hasDescendants = hasDescendants(name);
62			if (!hasDescendants && !ConfigurationPropertyName.EMPTY.equals(name)) {
63				for (ConfigurationPropertySource source : getContext().getSources()) {
64					ConfigurationProperty property = source.getConfigurationProperty(name);
65					if (property != null) {
66						getContext().setConfigurationProperty(property);
67						Object result = getContext().getPlaceholdersResolver().resolvePlaceholders(property.getValue());
68						if (result instanceof CharSequence charSequence && charSequence.isEmpty()) {
69							return createMap(target);
70						}
71						return getContext().getConverter().convert(result, target);
72					}
73				}
74			}
75			Map<Object, Object> map = createMap(target);
76			for (ConfigurationPropertySource source : getContext().getSources()) {
77				if (!ConfigurationPropertyName.EMPTY.equals(name)) {
78					source = source.filter(name::isAncestorOf);
79				}
80				new EntryBinder(name, resolvedTarget, elementBinder).bindEntries(source, map);
81			}
82			return map.isEmpty() ? null : map;
83		}
84	
85		private Map<Object, Object> createMap(Bindable<?> target) {
86			Class<?> mapType = (target.getValue() != null) ? Map.class : target.getType().resolve(Object.class);
87			if (EnumMap.class.isAssignableFrom(mapType)) {
88				Class<?> keyType = target.getType().asMap().resolveGeneric(0);
89				return CollectionFactory.createMap(mapType, keyType, 0);
90			}
91			return CollectionFactory.createMap(mapType, 0);
92		}
93	
94		private boolean hasDescendants(ConfigurationPropertyName name) {
95			for (ConfigurationPropertySource source : getContext().getSources()) {
96				if (source.containsDescendantOf(name) == ConfigurationPropertyState.PRESENT) {
97					return true;
98				}
99			}
100			return false;
101		}
102	
103		private Bindable<?> resolveTarget(Bindable<?> target) {
104			Class<?> type = target.getType().resolve(Object.class);
105			if (Properties.class.isAssignableFrom(type)) {
106				return STRING_STRING_MAP;
107			}
108			return target;
109		}
110	
111		@Override
112		protected Map<Object, Object> merge(Supplier<Map<Object, Object>> existing, Map<Object, Object> additional) {
113			Map<Object, Object> existingMap = getExistingIfPossible(existing);
114			if (existingMap == null) {
115				return additional;
116			}
117			try {
118				existingMap.putAll(additional);
119				return copyIfPossible(existingMap);
120			}
121			catch (UnsupportedOperationException ex) {
122				Map<Object, Object> result = createNewMap(additional.getClass(), existingMap);
123				result.putAll(additional);
124				return result;
125			}
126		}
127	
128		private @Nullable Map<Object, Object> getExistingIfPossible(Supplier<Map<Object, Object>> existing) {
129			try {
130				return existing.get();
131			}
132			catch (Exception ex) {
133				return null;
134			}
135		}
136	
137		private Map<Object, Object> copyIfPossible(Map<Object, Object> map) {
138			try {
139				return createNewMap(map.getClass(), map);
140			}
141			catch (Exception ex) {
142				return map;
143			}
144		}
145	
146		private Map<Object, Object> createNewMap(Class<?> mapClass, Map<Object, Object> map) {
147			Map<Object, Object> result = CollectionFactory.createMap(mapClass, map.size());
148			result.putAll(map);
149			return result;
150		}
151	
152		private class EntryBinder {
153	
154			private final ConfigurationPropertyName root;
155	
156			private final AggregateElementBinder elementBinder;
157	
158			private final ResolvableType mapType;
159	
160			private final ResolvableType keyType;
161	
162			private final ResolvableType valueType;
163	
164			private final Class<?> resolvedValueType;
165	
166			private final boolean valueTreatedAsNestedMap;
167	
168			private final Bindable<Object> bindableMapType;
169	
170			private final Bindable<Object> bindableValueType;
171	
172			EntryBinder(ConfigurationPropertyName root, Bindable<?> target, AggregateElementBinder elementBinder) {
173				this.root = root;
174				this.elementBinder = elementBinder;
175				this.mapType = target.getType().asMap();
176				this.keyType = this.mapType.getGeneric(0);
177				this.valueType = this.mapType.getGeneric(1);
178				this.resolvedValueType = this.valueType.resolve(Object.class);
179				this.valueTreatedAsNestedMap = Object.class.equals(this.resolvedValueType);
180				this.bindableMapType = Bindable.of(this.mapType);
181				this.bindableValueType = Bindable.of(this.valueType);
182			}
183	
184			void bindEntries(ConfigurationPropertySource source, Map<Object, Object> map) {
185				if (source instanceof IterableConfigurationPropertySource iterableSource) {
186					for (ConfigurationPropertyName name : iterableSource) {
187						ConfigurationPropertyName entryName = getEntryName(source, name);
188						Object key = getContext().getConverter().convert(getKeyName(entryName), this.keyType);
189						Bindable<?> valueBindable = getValueBindable(name);
190						map.computeIfAbsent(key, (k) -> this.elementBinder.bind(entryName, valueBindable));
191					}
192				}
193			}
194	
195			private Bindable<?> getValueBindable(ConfigurationPropertyName name) {
196				return (!isParentOf(name) && this.valueTreatedAsNestedMap) ? this.bindableMapType : this.bindableValueType;
197			}
198	
199			private ConfigurationPropertyName getEntryName(ConfigurationPropertySource source,
200					ConfigurationPropertyName name) {
201				if (Collection.class.isAssignableFrom(this.resolvedValueType) || this.valueType.isArray()) {
202					return chopNameAtNumericIndex(name);
203				}
204				if (!isParentOf(name) && (this.valueTreatedAsNestedMap || !isScalarValue(source, name))) {
205					return name.chop(this.root.getNumberOfElements() + 1);
206				}
207				return name;
208			}
209	
210			private boolean isParentOf(ConfigurationPropertyName name) {
211				return this.root.isParentOf(name);
212			}
213	
214			private ConfigurationPropertyName chopNameAtNumericIndex(ConfigurationPropertyName name) {
215				int start = this.root.getNumberOfElements() + 1;
216				int size = name.getNumberOfElements();
217				for (int i = start; i < size; i++) {
218					if (name.isNumericIndex(i)) {
219						return name.chop(i);
220					}
221				}
222				return name;
223			}
224	
225			private boolean isScalarValue(ConfigurationPropertySource source, ConfigurationPropertyName name) {
226				Class<?> resolved = this.valueType.resolve(Object.class);
227				if (!resolved.getName().startsWith("java.lang") && !resolved.isEnum()) {
228					return false;
229				}
230				ConfigurationProperty property = source.getConfigurationProperty(name);
231				if (property == null) {
232					return false;
233				}
234				Object value = property.getValue();
235				value = getContext().getPlaceholdersResolver().resolvePlaceholders(value);
236				return getContext().getConverter().canConvert(value, this.valueType);
237			}
238	
239			private String getKeyName(ConfigurationPropertyName name) {
240				StringBuilder result = new StringBuilder();
241				for (int i = this.root.getNumberOfElements(); i < name.getNumberOfElements(); i++) {
242					if (!result.isEmpty()) {
243						result.append('.');
244					}
245					result.append(name.getElement(i, Form.ORIGINAL));
246				}
247				return result.toString();
248			}
249	
250		}
251	
252	}
