17	package org.springframework.boot.diagnostics;
18	
19	import java.util.ArrayList;
20	import java.util.Collections;
21	import java.util.List;
22	
23	import org.apache.commons.logging.Log;
24	import org.apache.commons.logging.LogFactory;
25	import org.jspecify.annotations.Nullable;
26	
27	import org.springframework.beans.factory.BeanFactory;
28	import org.springframework.boot.SpringBootExceptionReporter;
29	import org.springframework.context.ConfigurableApplicationContext;
30	import org.springframework.core.env.Environment;
31	import org.springframework.core.io.support.SpringFactoriesLoader;
32	import org.springframework.core.io.support.SpringFactoriesLoader.ArgumentResolver;
33	import org.springframework.core.io.support.SpringFactoriesLoader.FailureHandler;
34	import org.springframework.core.log.LogMessage;
35	
36	/**
37	 * Utility to trigger {@link FailureAnalyzer} and {@link FailureAnalysisReporter}
38	 * instances loaded from {@code spring.factories}.
39	 * <p>
40	 * A {@code FailureAnalyzer} that requires access to the {@link BeanFactory} or
41	 * {@link Environment} in order to perform its analysis can implement a constructor that
42	 * accepts arguments of one or both of these types.
43	 *
44	 * @author Andy Wilkinson
45	 * @author Phillip Webb
46	 * @author Stephane Nicoll
47	 * @author Scott Frederick
48	 */
49	final class FailureAnalyzers implements SpringBootExceptionReporter {
50	
51		private static final Log logger = LogFactory.getLog(FailureAnalyzers.class);
52	
53		private final SpringFactoriesLoader springFactoriesLoader;
54	
55		private final List<FailureAnalyzer> analyzers;
56	
57		public FailureAnalyzers(@Nullable ConfigurableApplicationContext context) {
58			this(context,
59					SpringFactoriesLoader.forDefaultResourceLocation((context != null) ? context.getClassLoader() : null));
60		}
61	
62		FailureAnalyzers(@Nullable ConfigurableApplicationContext context, SpringFactoriesLoader springFactoriesLoader) {
63			this.springFactoriesLoader = springFactoriesLoader;
64			this.analyzers = loadFailureAnalyzers(context, this.springFactoriesLoader);
65		}
66	
67		private static List<FailureAnalyzer> loadFailureAnalyzers(@Nullable ConfigurableApplicationContext context,
68				SpringFactoriesLoader springFactoriesLoader) {
69			List<FailureAnalyzer> analyzers = new ArrayList<>(springFactoriesLoader.load(FailureAnalyzer.class,
70					getArgumentResolver(context), FailureHandler.logging(logger)));
71			analyzers.add(FailureAnalyzedException::analyze);
72			return Collections.unmodifiableList(analyzers);
73		}
74	
75		private static @Nullable ArgumentResolver getArgumentResolver(@Nullable ConfigurableApplicationContext context) {
76			if (context == null) {
77				return null;
78			}
79			ArgumentResolver argumentResolver = ArgumentResolver.of(BeanFactory.class, context.getBeanFactory());
80			argumentResolver = argumentResolver.and(Environment.class, context.getEnvironment());
81			return argumentResolver;
82		}
83	
84		@Override
85		public boolean reportException(Throwable failure) {
86			FailureAnalysis analysis = analyze(failure, this.analyzers);
87			return report(analysis);
88		}
89	
90		private @Nullable FailureAnalysis analyze(Throwable failure, List<FailureAnalyzer> analyzers) {
91			for (FailureAnalyzer analyzer : analyzers) {
92				try {
93					FailureAnalysis analysis = analyzer.analyze(failure);
94					if (analysis != null) {
95						return analysis;
96					}
97				}
98				catch (Throwable ex) {
99					logger.trace(LogMessage.format("FailureAnalyzer %s failed", analyzer), ex);
100				}
101			}
102			return null;
103		}
104	
105		private boolean report(@Nullable FailureAnalysis analysis) {
106			List<FailureAnalysisReporter> reporters = this.springFactoriesLoader.load(FailureAnalysisReporter.class);
107			if (analysis == null || reporters.isEmpty()) {
108				return false;
109			}
110			for (FailureAnalysisReporter reporter : reporters) {
111				reporter.report(analysis);
112			}
113			return true;
114		}
115	
116	}
